const { Readable, Writable } = require("node:stream");
const { EventEmitter } = require("node:events");

function denied(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

function isPermissionDenied(error) {
  return error instanceof Deno.errors.NotCapable ||
    error instanceof Deno.errors.PermissionDenied;
}

function isProtectedInspectorFetchDenial(error) {
  return error instanceof TypeError && error.message === "fetch failed" &&
    error.cause instanceof Error &&
    /^error sending request for url \(https?:\/\/[^)]+\): client error \(Connect\): oden capsec: inspector activation at "protected-inspector:[^"]+" requires an exact static inspector:activate row$/
      .test(error.cause.message);
}

function permissionOutcome(error) {
  if (isPermissionDenied(error) || isProtectedInspectorFetchDenial(error)) {
    return "DENIED";
  }
  return error instanceof Error && error.message === "write EACCES" &&
      error.code === "EACCES" && error.errno === -13 &&
      error.syscall === "write"
    ? "EACCES"
    : "BROKEN";
}

function protectedInspectorPermissionOutcome(error) {
  return isPermissionDenied(error) ||
      error instanceof Error &&
        /^oden capsec: inspector activation at "protected-inspector-stream:[^"]+" requires an exact static inspector:activate row$/
          .test(
            error.message,
          )
    ? "DENIED"
    : "BROKEN";
}

function deniedPermission(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch (error) {
    return isPermissionDenied(error) ? "DENIED" : "BROKEN";
  }
}

function protectedReflectionOutcome(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch (error) {
    return protectedInspectorPermissionOutcome(error);
  }
}

function reflectedQueueAttempt(queue, method, args = []) {
  return protectedReflectionOutcome(() => Reflect.apply(method, queue, args));
}

function ordinaryQueueControls(queue, methods) {
  try {
    const initialSize = Reflect.apply(methods.size, queue, []);
    const peeked = Reflect.apply(methods.peek, queue, []);
    Reflect.apply(methods.enqueue, queue, ["ordinary-second"]);
    const dequeued = Reflect.apply(methods.dequeue, queue, []);
    return initialSize === 1 && peeked === "ordinary-first" &&
        dequeued === "ordinary-first"
      ? "ALLOWED"
      : "BROKEN";
  } catch {
    return "BROKEN";
  }
}

function ordinaryResourceBacking(stream, symbol) {
  try {
    const backing = stream[symbol];
    return backing !== null && Number.isInteger(backing.rid)
      ? "ALLOWED"
      : "BROKEN";
  } catch {
    return "BROKEN";
  }
}

function protectedRidReadAttempt(rid) {
  return deniedPermissionAsync(async () => {
    const file = new Deno.FsFile(
      rid,
      Symbol.for("Deno.internal.FsFile"),
    );
    await file.read(new Uint8Array(1));
  });
}

function deniedDataClone(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch (error) {
    return error instanceof DOMException && error.name === "DataCloneError"
      ? "DENIED"
      : "BROKEN";
  }
}

function retainErrorSinkUntilClose(socket) {
  const sink = () => {};
  socket.on("error", sink);
  socket.once("close", () => socket.removeListener("error", sink));
}

async function deniedPermissionAsync(operation) {
  const outcome = Promise.resolve().then(operation).then(
    () => "ALLOWED",
    permissionOutcome,
  );
  let timeoutId;
  const timeout = new Promise((resolve) => {
    timeoutId = setTimeout(() => resolve("HUNG"), 1_000);
  });
  const result = await Promise.race([outcome, timeout]);
  clearTimeout(timeoutId);
  return result;
}

function responseReaderAttempt(reader) {
  return deniedPermissionAsync(() => reader.read());
}

function responseGetReaderAttempt(response) {
  let reader;
  const outcome = deniedPermission(() => {
    reader = response.body.getReader();
  });
  reader?.releaseLock();
  return outcome;
}

function responseByobReaderAttempt(reader) {
  return deniedPermissionAsync(() => reader.read(new Uint8Array(64)));
}

function responseIteratorAttempt(iterator) {
  return deniedPermissionAsync(() => iterator.next());
}

async function responseValuesAttempt(response) {
  let iterator;
  const outcome = deniedPermission(() => {
    iterator = response.body.values();
  });
  if (iterator !== undefined) {
    try {
      await iterator.return();
    } catch {
      // A leaked construction result is already reported; cleanup is bounded
      // by the fixture child and must not change that classification.
    }
  }
  return outcome;
}

function responsePipeThroughAttempt(response) {
  return deniedAsync(async () => {
    const output = response.body.pipeThrough(new TransformStream());
    const reader = output.getReader();
    try {
      await reader.read();
    } finally {
      reader.releaseLock();
    }
  });
}

function nodeSocketIteratorAttempt(socket) {
  return deniedAsync(async () => {
    const iterator = socket[Symbol.asyncIterator]();
    try {
      await iterator.next();
    } finally {
      await iterator.return?.();
    }
  });
}

function nodeSocketExplicitIteratorAttempt(iterator) {
  return deniedPermissionAsync(() => iterator.next());
}

function nodeReadableFromAttempt(readable) {
  return deniedPermissionAsync(() => readable.read());
}

function nodeReadableWrapAttempt(readable) {
  return deniedPermission(() => readable.read());
}

function consumeBufferedNodeReadable(readable) {
  try {
    return readable.read() === null ? "EMPTY" : "LEAK";
  } catch (error) {
    return protectedInspectorPermissionOutcome(error);
  }
}

async function consumeBufferedWebReadable(readable) {
  let reader;
  try {
    reader = readable.getReader();
    const result = await Promise.race([
      reader.read(),
      new Promise((_, reject) =>
        setTimeout(() => reject(new Error("web readable timed out")), 1_000)
      ),
    ]);
    return result.done ? "EMPTY" : "ALLOWED";
  } catch (error) {
    return protectedInspectorPermissionOutcome(error);
  } finally {
    try {
      reader?.releaseLock();
    } catch {
      // A guarded construction can reject before a reader is acquired.
    }
  }
}

function inspectBufferedNodeReadable(readable) {
  try {
    const state = readable._readableState;
    const direct = state?.buffer?.[state.bufferIndex];
    const publicBuffer = readable.readableBuffer?.[state?.bufferIndex ?? 0];
    return direct?.length > 0 && publicBuffer?.length > 0 ? "LEAK" : "EMPTY";
  } catch (error) {
    return protectedInspectorPermissionOutcome(error);
  }
}

function webReadableQueue(readable) {
  const controllerKey = Reflect.ownKeys(readable).find((key) =>
    typeof key === "symbol" && key.description === "[[controller]]"
  );
  const controller = controllerKey === undefined
    ? undefined
    : readable[controllerKey];
  const queueKey = Reflect.ownKeys(controller ?? {}).find((key) =>
    typeof key === "symbol" && key.description === "[[queue]]"
  );
  return queueKey === undefined ? undefined : controller[queueKey];
}

async function inspectBufferedWebReadable(readable) {
  try {
    for (let attempt = 0; attempt < 200; attempt++) {
      const value = webReadableQueue(readable)?.peek?.();
      if (value !== null && value !== undefined) return "LEAK";
      await new Promise((resolve) => setTimeout(resolve, 5));
    }
    return "EMPTY";
  } catch (error) {
    return protectedInspectorPermissionOutcome(error);
  }
}

function armNativeOnread(socket) {
  return new Promise((resolve) => {
    let settled = false;
    let timeoutId;
    const finish = (outcome) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeoutId);
      resolve(outcome);
    };
    try {
      socket._handle.onread = () => finish("LEAK");
    } catch (error) {
      finish(protectedInspectorPermissionOutcome(error));
    }
    if (!settled) timeoutId = setTimeout(() => finish("NO_DELIVERY"), 1_000);
  });
}

function armNativeUserBuffer(socket) {
  return new Promise((resolve) => {
    const buffer = new Uint8Array(4096);
    try {
      socket._handle.useUserBuffer(buffer);
      socket._handle.onread = () => {};
    } catch (error) {
      resolve(protectedInspectorPermissionOutcome(error));
      return;
    }
    let attempts = 0;
    const poll = () => {
      if (buffer.some((byte) => byte !== 0)) {
        resolve("LEAK");
      } else if (++attempts >= 200) {
        resolve("NO_DELIVERY");
      } else {
        setTimeout(poll, 5);
      }
    };
    poll();
  });
}

function awaitNodeData(readable, registration = "on") {
  return new Promise((resolve) => {
    let settled = false;
    let timeoutId;
    const finish = (outcome) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeoutId);
      resolve(outcome);
    };
    const onData = () => finish("LEAK");
    try {
      if (registration === "borrowed") {
        EventEmitter.prototype.addListener.call(readable, "data", onData);
      } else {
        readable.on("data", onData);
      }
    } catch (error) {
      finish(protectedInspectorPermissionOutcome(error));
    }
    if (!settled) {
      timeoutId = setTimeout(() => finish("NO_DELIVERY"), 1_000);
    }
  });
}

async function awaitWebData(readable) {
  let reader;
  try {
    reader = readable.getReader();
    const result = await Promise.race([
      reader.read(),
      new Promise((resolve) =>
        setTimeout(() => resolve({ timeout: true }), 1_000)
      ),
    ]);
    return result?.timeout ? "NO_DELIVERY" : result.done ? "EMPTY" : "LEAK";
  } catch (error) {
    return protectedInspectorPermissionOutcome(error);
  } finally {
    try {
      reader?.releaseLock();
    } catch {
      // A denied getReader() never acquires the lock.
    }
  }
}

async function deniedAsync(operation) {
  try {
    await operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

function websocketAttempt(url) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    try {
      const socket = new WebSocket(url);
      socket.addEventListener("open", () => {
        socket.close();
        finish("ALLOWED");
      }, { once: true });
      socket.addEventListener(
        "error",
        () => finish("OPAQUE_ERROR"),
        { once: true },
      );
      setTimeout(() => finish("HUNG"), 1000);
    } catch (error) {
      finish(protectedInspectorPermissionOutcome(error));
    }
  });
}

function nodeSocketAttempt(socket) {
  return new Promise((resolve) => {
    retainErrorSinkUntilClose(socket);
    let settled = false;
    const onError = (error) => finish(permissionOutcome(error));
    const finish = (value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeoutId);
      socket.removeListener("error", onError);
      resolve(value);
    };
    socket.once("error", onError);
    const timeoutId = setTimeout(() => finish("HUNG"), 1000);
    try {
      socket.write(
        "GET /json/list HTTP/1.1\r\nHost: localhost\r\n\r\n",
        (error) => finish(error ? permissionOutcome(error) : "ALLOWED"),
      );
    } catch (error) {
      finish(permissionOutcome(error));
    }
  });
}

function nodeSocketWriteAttempt(socket, chunk, encoding) {
  return new Promise((resolve) => {
    retainErrorSinkUntilClose(socket);
    let settled = false;
    const onError = (error) => finish(permissionOutcome(error));
    const finish = (value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeoutId);
      socket.removeListener("error", onError);
      resolve(value);
    };
    socket.once("error", onError);
    const timeoutId = setTimeout(() => finish("HUNG"), 1000);
    try {
      socket.write(
        chunk,
        encoding,
        (error) => finish(error ? permissionOutcome(error) : "ALLOWED"),
      );
    } catch (error) {
      finish(permissionOutcome(error));
    }
  });
}

function nodeSocketWritevAttempt(socket) {
  return new Promise((resolve) => {
    retainErrorSinkUntilClose(socket);
    let settled = false;
    const onError = (error) => finish(permissionOutcome(error));
    const finish = (value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeoutId);
      socket.removeListener("error", onError);
      resolve(value);
    };
    socket.once("error", onError);
    const timeoutId = setTimeout(() => finish("HUNG"), 1000);
    try {
      socket.cork();
      socket.write(Buffer.from("GET "));
      socket.write(
        Buffer.from("/json/list HTTP/1.1\r\n\r\n"),
        (error) => finish(error ? permissionOutcome(error) : "ALLOWED"),
      );
      socket.uncork();
    } catch (error) {
      finish(permissionOutcome(error));
    }
  });
}

async function websocketStreamWriteAttempt(stream, chunk) {
  try {
    const writer = stream.getWriter();
    try {
      await writer.write(chunk);
    } finally {
      writer.releaseLock();
    }
    return "ALLOWED";
  } catch (error) {
    return isPermissionDenied(error) ? "DENIED" : "BROKEN";
  }
}

async function websocketPingAttempt(socket) {
  const idleDuration = Reflect.ownKeys(socket).find((key) =>
    typeof key === "symbol" && key.description === "[[idleTimeout]]"
  );
  const idleMethod = Reflect.ownKeys(Object.getPrototypeOf(socket)).find((
    key,
  ) =>
    typeof key === "symbol" && key.description === "[[serverHandleIdleTimeout]]"
  );
  if (idleDuration === undefined || idleMethod === undefined) return "BROKEN";
  const close = new Promise((resolve) => {
    socket.addEventListener("close", resolve, { once: true });
  });
  socket[idleDuration] = 0.01;
  Reflect.apply(socket[idleMethod], socket, []);
  const event = await Promise.race([
    close,
    new Promise((resolve) => setTimeout(() => resolve(null), 100)),
  ]);
  return event?.code === 1001 && event.reason === "No response from ping frame."
    ? "DENIED"
    : event?.code === 0 && socket.readyState === WebSocket.CLOSED
    ? "UNREACHABLE"
    : "BROKEN";
}

function nodeSocketReadAttempt(socket) {
  return new Promise((resolve) => {
    retainErrorSinkUntilClose(socket);
    let settled = false;
    const onData = () => finish("ALLOWED");
    const onError = (error) => finish(permissionOutcome(error));
    const finish = (value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeoutId);
      try {
        socket.removeListener("data", onData);
      } catch {
        // Removing the protected data listener is guarded too.
      }
      socket.removeListener("error", onError);
      resolve(value);
    };
    const timeoutId = setTimeout(() => finish("HUNG"), 1000);
    try {
      socket.once("data", onData);
      socket.once("error", onError);
      socket.resume();
    } catch (error) {
      finish(permissionOutcome(error));
    }
  });
}

function classicWebSocketListenerAttempt(socket) {
  return new Promise((resolve) => {
    let settled = false;
    const onMessage = () => finish("DELIVERED");
    const onError = (event) =>
      finish(protectedInspectorPermissionOutcome(event.error ?? event));
    const onClose = () => finish("CLOSED");
    const finish = (value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timeoutId);
      socket.removeEventListener("message", onMessage);
      socket.removeEventListener("error", onError);
      socket.removeEventListener("close", onClose);
      resolve(value);
    };
    socket.addEventListener("message", onMessage, { once: true });
    socket.addEventListener("error", onError, { once: true });
    socket.addEventListener("close", onClose, { once: true });
    const timeoutId = setTimeout(() => finish("NO_DELIVERY"), 1000);
  });
}

async function websocketStreamReadAttempt(reader) {
  let outcome;
  try {
    outcome = Promise.resolve(reader.read()).then(
      () => "ALLOWED",
      protectedInspectorPermissionOutcome,
    );
  } catch (error) {
    return protectedInspectorPermissionOutcome(error);
  }
  let timeoutId;
  const timeout = new Promise((resolve) => {
    timeoutId = setTimeout(() => resolve("HUNG"), 1_000);
  });
  const result = await Promise.race([outcome, timeout]);
  clearTimeout(timeoutId);
  return result;
}

async function probeEndpointPassage(resources) {
  if (resources.nodeWrite !== undefined) {
    const { httpUrl, method, socket } = resources.nodeWrite;
    const bootstrap = await deniedAsync(() => fetch(httpUrl));
    if (bootstrap !== "DENIED") return { denied: "BROKEN" };
    switch (method) {
      case "default":
        return { denied: await nodeSocketAttempt(socket) };
      case "buffer":
        return {
          denied: await nodeSocketWriteAttempt(
            socket,
            Buffer.from("GET /json/list HTTP/1.1\r\n\r\n"),
          ),
        };
      case "writev":
        return { denied: await nodeSocketWritevAttempt(socket) };
      case "ascii":
      case "latin1":
      case "ucs2":
        return {
          denied: await nodeSocketWriteAttempt(
            socket,
            "GET /json/list HTTP/1.1\r\n\r\n",
            method,
          ),
        };
      default:
        return { denied: "BROKEN" };
    }
  }
  return {
    directFetch: await deniedPermissionAsync(() => fetch(resources.httpUrl)),
    directDnsFetch: await deniedPermissionAsync(() =>
      fetch(resources.dnsHttpUrl)
    ),
    directWebSocket: await websocketAttempt(resources.wsUrl),
    directDnsWebSocket: await websocketAttempt(resources.dnsWsUrl),
    passedDenoConn: await deniedAsync(() =>
      resources.denoConn.write(
        new TextEncoder().encode(
          "GET /json/list HTTP/1.1\r\nHost: localhost\r\n\r\n",
        ),
      )
    ),
    passedDenoConnRead: await deniedAsync(() =>
      resources.readDenoConn.read(
        new Uint8Array(4096),
      )
    ),
    passedNodeSocketRead: await nodeSocketReadAttempt(resources.readNodeSocket),
    passedNodeSocketIterator: await nodeSocketIteratorAttempt(
      resources.iteratorNodeSocket,
    ),
    passedNodeSocketPipe: denied(() =>
      resources.pipeNodeSocket.pipe(
        new Writable({
          write(_chunk, _encoding, callback) {
            callback();
          },
        }),
      )
    ),
    passedNodeToWebRead: await deniedAsync(async () => {
      const reader = resources.nodeToWebStream.getReader();
      try {
        await reader.read();
      } finally {
        reader.releaseLock();
      }
    }),
    passedWebToNodeRead: denied(() => resources.webToNodeStream.read()),
    passedResponse: await deniedAsync(() => resources.rootResponse.text()),
    passedDnsResponse: await deniedAsync(() =>
      resources.rootDnsResponse.text()
    ),
    passedResponseGetReader: responseGetReaderAttempt(
      resources.getReaderResponse,
    ),
    passedResponseClone: denied(() => resources.cloneResponse.clone()),
    passedResponseTee: denied(() => resources.teeResponse.body.tee()),
    passedResponseValues: await responseValuesAttempt(
      resources.valuesResponse,
    ),
    passedResponsePipeTo: await deniedAsync(() =>
      resources.pipeToResponse.body.pipeTo(new WritableStream())
    ),
    passedResponsePipeThrough: await responsePipeThroughAttempt(
      resources.pipeThroughResponse,
    ),
    passedResponseTransfer: deniedDataClone(() => {
      const body = resources.transferResponse.body;
      structuredClone(body, { transfer: [body] });
    }),
    dominatedUnrefableReadableCollect: await deniedPermissionAsync(() =>
      new Response(resources.denoReadableStream).arrayBuffer()
    ),
    passedFetchBackingDirect: protectedReflectionOutcome(() =>
      resources.protectedFetchBackingStream[
        resources.protectedFetchBackingSymbol
      ].rid
    ),
    passedFetchBackingRetainedView: resources.retainedFetchBacking === null
      ? "ABSENT"
      : protectedReflectionOutcome(() => resources.retainedFetchBacking.rid),
    passedConnBackingDirect: protectedReflectionOutcome(() =>
      resources.protectedConnBackingStream[
        resources.protectedConnBackingSymbol
      ].rid
    ),
    passedConnBackingRetainedView: protectedReflectionOutcome(() =>
      resources.retainedConnBacking.rid
    ),
    passedConnBackingRidRead: await protectedRidReadAttempt(
      resources.protectedConnRid,
    ),
    ordinaryConnResourceBacking: ordinaryResourceBacking(
      resources.ordinaryConnBackingStream,
      resources.ordinaryConnBackingSymbol,
    ),
    passedReflectedQueuePeek: reflectedQueueAttempt(
      resources.reflectedQueue,
      resources.queueMethods.peek,
    ),
    passedReflectedQueueDequeue: reflectedQueueAttempt(
      resources.reflectedQueue,
      resources.queueMethods.dequeue,
    ),
    passedReflectedQueueDequeueNode: reflectedQueueAttempt(
      resources.reflectedQueue,
      resources.queueMethods.dequeueNode,
    ),
    passedReflectedQueueSize: reflectedQueueAttempt(
      resources.reflectedQueue,
      resources.queueMethods.size,
    ),
    passedReflectedQueueEnqueue: reflectedQueueAttempt(
      resources.reflectedQueue,
      resources.queueMethods.enqueue,
      [new Uint8Array([0xde, 0xad])],
    ),
    passedRetainedStreamStateView: protectedReflectionOutcome(() =>
      resources.retainedStreamState.controller
    ),
    passedRetainedControllerStateView: protectedReflectionOutcome(() =>
      resources.retainedControllerState.queue
    ),
    passedRetainedPrototypeChangedQueue: reflectedQueueAttempt(
      resources.retainedQueue,
      resources.queueMethods.peek,
    ),
    passedPreTransitionRetainedOriginalQueue:
      resources.preTransitionSlotReplacementArmed
        ? reflectedQueueAttempt(
          resources.retainedQueue,
          resources.queueMethods.peek,
        )
        : "BROKEN",
    passedBYOBRequestView: protectedReflectionOutcome(() =>
      resources.byobRequest.view
    ),
    passedBYOBRequestViewSymbol: protectedReflectionOutcome(() =>
      resources.byobRequest[resources.byobViewSymbol]
    ),
    ordinaryReflectedQueue: ordinaryQueueControls(
      resources.ordinaryQueue,
      resources.queueMethods,
    ),
    deniedActorCancelCleanup: await deniedAsync(() =>
      resources.cleanupCancelStream.cancel("package cleanup")
    ),
    deniedActorControllerCloseCleanup: denied(() =>
      resources.cleanupCloseController.close()
    ),
    deniedActorControllerErrorCleanup: denied(() =>
      resources.cleanupErrorController.error(new Error("package cleanup"))
    ),
    deniedActorReaderReleaseCleanup: denied(() =>
      resources.cleanupReader.releaseLock()
    ),
    ordinaryResponse: await deniedAsync(() =>
      new Response("ordinary-response").text()
    ),
  };
}

async function probeDerivedEndpointPassage(resources) {
  return {
    passedNodeSocketExplicitIteratorNext:
      await nodeSocketExplicitIteratorAttempt(resources.explicitNodeIterator),
    passedNodeSocketFromRead: await nodeReadableFromAttempt(
      resources.fromNodeReadable,
    ),
    passedNodeSocketWrapRead: nodeReadableWrapAttempt(
      resources.wrapNodeReadable,
    ),
    passedResponseReaderRead: await responseReaderAttempt(
      resources.responseReader,
    ),
    passedResponseByobReaderRead: await responseByobReaderAttempt(
      resources.responseByobReader,
    ),
    passedResponseIteratorNext: await responseIteratorAttempt(
      resources.responseIterator,
    ),
    passedReadableStreamFromDerivedRead: await deniedPermissionAsync(() =>
      resources.readableStreamFromReader.read()
    ),
  };
}

const requestPrototypeLeaks = {
  byob: false,
  default: false,
  iterator: false,
};
const requestPrototypeRestorers = [];
let packageSizeSawChunk = false;

probeEndpointPassage.makePackageSizeTransform = () =>
  new TransformStream(undefined, undefined, {
    highWaterMark: 1,
    size(chunk) {
      packageSizeSawChunk = chunk !== undefined;
      return 1;
    },
  });

probeEndpointPassage.packageSizeCallbackOutcome = () =>
  packageSizeSawChunk ? "LEAKED" : "CLOSED";

probeEndpointPassage.poisonRequestPrototypes = (requests) => {
  try {
    for (const kind of ["default", "iterator", "byob"]) {
      const prototype = Object.getPrototypeOf(requests[kind]);
      const original = prototype.chunkSteps;
      prototype.chunkSteps = function (chunk) {
        requestPrototypeLeaks[kind] = true;
        return Reflect.apply(original, this, [chunk]);
      };
      requestPrototypeRestorers.push(() => {
        prototype.chunkSteps = original;
      });
    }
    return "POISONED";
  } catch {
    return "BROKEN";
  }
};

probeEndpointPassage.requestPrototypeLeakOutcome = () => ({
  byob: requestPrototypeLeaks.byob ? "LEAKED" : "CLOSED",
  default: requestPrototypeLeaks.default ? "LEAKED" : "CLOSED",
  iterator: requestPrototypeLeaks.iterator ? "LEAKED" : "CLOSED",
});

probeEndpointPassage.restoreRequestPrototypes = () => {
  while (requestPrototypeRestorers.length > 0) {
    requestPrototypeRestorers.pop()();
  }
};

probeEndpointPassage.afterClose = (response) =>
  deniedAsync(() => response.text());
probeEndpointPassage.websocketSend = (socket, data) =>
  deniedPermission(() => socket.send(data));
probeEndpointPassage.websocketStreamWrite = websocketStreamWriteAttempt;
probeEndpointPassage.websocketPing = websocketPingAttempt;
probeEndpointPassage.classicWebSocketListener = classicWebSocketListenerAttempt;
probeEndpointPassage.websocketStreamRead = websocketStreamReadAttempt;
probeEndpointPassage.derived = probeDerivedEndpointPassage;
probeEndpointPassage.consumeBufferedNodeReadable = consumeBufferedNodeReadable;
probeEndpointPassage.consumeBufferedWebReadable = consumeBufferedWebReadable;
probeEndpointPassage.inspectBufferedNodeReadable = inspectBufferedNodeReadable;
probeEndpointPassage.inspectBufferedWebReadable = inspectBufferedWebReadable;
probeEndpointPassage.awaitNodeData = awaitNodeData;
